'use strict';
const $ = id => document.getElementById(id);
const lessons = [
 {chapter:'A working link',title:'Every click has a journey.',subtitle:'Start small. One visitor, one server, one link.',tag:'A quiet beginning',type:'THE STARTING POINT',heading:'Let’s follow a click.',copy:'<p>You share <strong>tiny.example/show</strong>. Behind that short address is a record containing the full destination.</p><p>The browser asks your API server for the destination. The API reads it from the database and returns a redirect. The browser can then visit the original site.</p>',takeLabel:'THE KEY IDEA',take:'The API handles the request. The database keeps the link record. They have different jobs.',change:null,deep:'This lesson focuses on resolving an existing short code. The redirect response contains a Location header; navigating to that destination is a separate browser request, omitted from this diagram. Link creation, DNS, TLS, and browser caching are outside this model.',experiment:'Send another click and follow its journey.',controls:'<button class="primary" data-action="request">Send a request</button>',route:'direct'},
 {chapter:'A popular link',title:'Then everyone shares it.',subtitle:'Same system. A very different kind of afternoon.',tag:'Traffic is growing',type:'SOMETHING CHANGES',heading:'A thousand identical questions.',copy:'<p>Your link gets shared in a busy community. People keep asking for <strong>the same destination</strong>.</p><p>In this starting design, every click still reads the database. Repeated work grows with traffic, even though the answer has not changed.</p>',takeLabel:'NOTICE THE PATTERN',take:'Many reads ask for the same small piece of data. Keep that in mind.',change:'More requests arrive. The architecture stays exactly the same.',deep:'Total users and requests per second are different measures. Here, the slider controls only the illustrative arrival rate. Real systems need measured request rates, workload characteristics, and capacity.',experiment:'Turn up the traffic. Which component repeats its work?',controls:'<label for="traffic">Request activity: <strong id="traffic-label">Low</strong></label><input id="traffic" type="range" min="1" max="5" value="1"><div id="feedback" class="feedback" role="status"></div>',route:'direct'},
 {chapter:'The database slows down',title:'The queue starts growing.',subtitle:'Before choosing a fix, look for the bottleneck.',tag:'Database under pressure',type:'THE PROBLEM',heading:'Adding servers isn’t always the fix.',copy:'<p>For this scenario, assume the API has spare capacity but <strong>the database cannot finish reads as quickly as they arrive</strong>. Requests begin waiting; some time out and fail, shown as red × markers at the database.</p><p>Adding API replicas would not remove those database reads. We need to address the repeated work—or otherwise increase the database’s effective capacity.</p>',takeLabel:'LOOK BEFORE YOU SCALE',take:'A bottleneck is the resource limiting this workload. Find it before changing the architecture.',change:'Database reads slow down. Some requests time out: red × markers show failures at the database.',deep:'In production, investigate query latency, indexes, locks, I/O, CPU, connection-pool wait times, and slow queries before assuming saturation. Caching is the choice explored here because this scenario has repeated reads of popular links; it is not a universal fix.',experiment:'What would you investigate first in this scenario?',controls:'<button class="secondary" data-answer="api">API replica count</button><button class="secondary" data-answer="db">Database read latency</button><div id="feedback" class="feedback" role="status"></div>',route:'slow'},
 {chapter:'Add a cache',title:'Popular links, faster reads.',subtitle:'Give repeated questions a shorter journey.',tag:'A cache joins the system',type:'A POSSIBLE SOLUTION',heading:'Keep a copy close by.',copy:'<p>Add a cache for recently requested destinations. The API <strong>checks the cache first</strong>.</p><p>On a <strong>miss</strong>, it reads the database, stores a temporary copy, and responds. On a later <strong>hit</strong>, it can use that copy without reading the database.</p>',takeLabel:'THE TRADE-OFF',take:'The cache reduces repeated reads when entries are reusable. It also adds another component and another copy to manage.',change:'Cache added. Watch a miss populate it, then try a cache hit.',deep:'This is the cache-aside pattern. The API owns the read-and-fill logic. A hit is possible only while a valid entry remains available; expiry, eviction, restarts, and new keys can cause misses. Cache failures and stampedes deserve their own lessons.',experiment:'Compare a cold cache with a repeated request.',controls:'<button class="secondary" data-action="miss">Run a cache miss</button><button class="primary" data-action="hit">Run a cache hit</button><div id="feedback" class="feedback" role="status"></div>',route:'miss'},
 {chapter:'When links change',title:'Two copies. One small catch.',subtitle:'A faster answer still needs to be the right answer.',tag:'The freshness question',type:'THE NEXT TRADE-OFF',heading:'What if the original changes?',copy:'<p>The owner updates the destination from <strong>/show-v1</strong> to <strong>/show-v2</strong>. The database has the new record, but the cache can still hold the old one.</p><p>In this example we give entries a <strong>time to live (TTL)</strong>. After expiry, the next lookup misses and refreshes the copy. Until then, a hit may return the old destination.</p>',takeLabel:'A DESIGN DECISION',take:'TTL limits how long a cached copy lives. If updates must take effect immediately, TTL alone is not enough.',change:'The original destination changed. The cached copy may now be stale.',deep:'Another strategy is to invalidate the cached entry on writes, but races, failed invalidations, and concurrent requests still need consideration. Cache TTL is distinct from browser or CDN caching of HTTP redirects.',experiment:'The database is now /show-v2. Try the old copy, then expire it.',controls:'<button class="secondary" data-action="stale">Read before expiry</button><button class="primary" data-action="expire">Expire and refresh</button><div id="feedback" class="feedback" role="status"></div>',route:'stale'},
 {chapter:'The bigger picture',title:'You’ve changed the journey.',subtitle:'One new component. A clearer understanding of why it exists.',tag:'Your system, evolved',type:'THE TAKEAWAY',heading:'A cache solves a particular problem.',copy:'<p>You began with a direct database lookup. Repeated reads created an opportunity to reuse answers. A cache shortened that path—but introduced <strong>misses, expiry, and stale data</strong>.</p><p>The useful question is not “does this system need Redis?” It is <strong>“what work are we repeating, and how fresh must the answer be?”</strong></p>',takeLabel:'TAKE THIS WITH YOU',take:'Understand the workload, locate the bottleneck, try a change, and account for its trade-offs.',change:'Recap: API + database became API + cache + database, with a freshness policy.',deep:'Other workloads may benefit more from indexes, query changes, database replicas, batching, or a different data model. This prototype explores one read-heavy scenario, rather than prescribing a complete production design.',experiment:'Revisit either journey. You can move freely between chapters.',controls:'<button class="secondary" data-action="miss">Replay a miss</button><button class="primary" data-action="hit">Replay a hit</button>',route:'hit'}
];
let trafficLevel=2, flowTime=0, nextArrival=0, flowSerial=0, flows=[], sent=0, completed=0, failed=0, databaseReads=0, cacheHits=0;
const trafficProfiles=[{users:1,label:'1 user',figures:1,interval:5500},{users:100,label:'100 users',figures:3,interval:1600},{users:1000,label:'1,000 users',figures:6,interval:900},{users:10000,label:'10,000 users',figures:10,interval:500},{users:1000000,label:'1M users',figures:15,interval:300}];
let step=0, route='direct', paused=matchMedia('(prefers-reduced-motion: reduce)').matches, segments=[], started=0, elapsed=0, previous=0;
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
const routes={
 direct:[['client-api','The visitor asks the API for a destination.'],['api-db','The API reads the original link record.'],['db-api','The database returns the destination.'],['api-client','The API sends a redirect to the visitor.']],
 slow:[['client-api','A new request reaches the API.'],['api-db','The database read joins the waiting work.',3],['db-api','The database eventually returns the result.'],['api-client','The waiting visitor receives the redirect.']],
 miss:[['client-api','The request reaches the API.'],['api-cache','The API checks the cache.'],['cache-api','Cache miss: there is no stored destination.'],['api-db','The API reads the link from the database.'],['db-api','The database returns the original record.'],['api-cache','The API stores a temporary copy in the cache.'],['cache-api','The cache confirms the write.'],['api-client','The API returns the destination to the visitor.']],
 hit:[['client-api','A repeat request reaches the API.'],['api-cache','The API checks the cached destination.'],['cache-api','Cache hit: the temporary copy is available.'],['api-client','The API responds without reading the database.']],
 stale:[['client-api','A request arrives after the original link changed.'],['api-cache','The API checks the existing cached copy.'],['cache-api','The cache still returns /show-v1.'],['api-client','The visitor receives the old destination.']]
};
function setRoute(name){resetTraffic();route=name;segments=routes[name];elapsed=0;started=0;previous=0;$('packets').replaceChildren();showTrace(0);}
function showTrace(i){$('trace-text').textContent=segments[i][1];$('trace-count').textContent=`${i+1} / ${segments.length}`;}
function render(){const l=lessons[step];$('step-label').textContent=`CHAPTER ${step+1} OF ${lessons.length} · A LINK WORTH SHARING`;$('scene-tag').textContent=l.tag;$('type').textContent=l.type;$('explain-title').textContent=l.heading;$('copy').innerHTML=l.copy;$('takeaway-label').textContent=l.takeLabel;$('takeaway').textContent=l.take;$('change-text').textContent=l.change || '';document.querySelector('.change').hidden=!l.change;$('deep-copy').textContent=l.deep;$('experiment-body').innerHTML=`<p>${l.experiment}</p>${l.controls}`;if(step===1 || step===2){$('experiment-body').innerHTML=`<p>Increase the audience and watch more requests travel through the system.${step===2?' Some database reads time out under this illustrative overload.':''}</p><label for="traffic">Audience: <strong id="traffic-label"></strong></label><input id="traffic" type="range" min="1" max="5" value="${trafficLevel+1}">${step===2?l.controls.replace(/<div id="feedback".*<\/div>/,''):''}<div id="feedback" class="feedback" role="status"></div>`;}renderAudience();$('experiment').open=false;document.querySelector('.deep').open=false;$('cache').style.display=step>=3?'':'none';$('cache-wires').style.display=step>=3?'':'none';$('cache-metrics').style.display=step>=3?'':'none';$('database').classList.toggle('busy',step===2);$('visitor-caption').textContent='Illustrative audience';renderAudience();$('cache-caption').textContent=step===4?'/show-v1 · old copy':'Temporary copy';$('route-label').querySelector('text').textContent=step===2?'Waiting on the database':step>=3?'Check the copy first':'One click. One lookup.';$('chapters').innerHTML=lessons.map((x,i)=>`<button class="chapter ${i===step?'active':i<step?'done':''}" data-step="${i}" ${i===step?'aria-current="step"':''}><b>${i<step?'✓':String(i+1).padStart(2,'0')}</b>${x.chapter}</button>`).join('');$('step-dots').innerHTML=lessons.map((x,i)=>`<button class="step-dot ${i===step?'active':''}" data-step="${i}" aria-label="Chapter ${i+1}: ${x.chapter}" ${i===step?'aria-current="step"':''}></button>`).join('');$('progress').style.width=`${(step+1)/lessons.length*100}%`;$('progress-label').textContent=`${step+1} of ${lessons.length} chapters`;$('back').disabled=step===0;$('next').textContent=step===5?'Start again':`Next: ${lessons[step+1].chapter}`;setRoute(l.route);syncPause();}
function syncPause(){$('pause').textContent=paused?'▷ Play':'Ⅱ Pause';$('pause').setAttribute('aria-pressed',String(paused));}
function go(i){step=Math.max(0,Math.min(5,i));location.hash=`step-${step+1}`;render();$('outline').classList.remove('open');$('outline-toggle').setAttribute('aria-expanded','false');}
function fromHash(){const m=location.hash.match(/^#step-([1-6])$/);step=m?Number(m[1])-1:0;render();}
$('next').onclick=()=>go(step===5?0:step+1);$('back').onclick=()=>go(step-1);$('pause').onclick=()=>{paused=!paused;syncPause()};$('replay').onclick=()=>{setRoute(route);paused=false;syncPause()};$('outline-toggle').onclick=()=>{const open=$('outline').classList.toggle('open');$('outline-toggle').setAttribute('aria-expanded',String(open));};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.step!==undefined)go(Number(b.dataset.step));if(b.dataset.answer){$('feedback').textContent=b.dataset.answer==='db'?'Exactly: in this scenario, database reads are taking longer. The evidence points there before adding API capacity.':'Check the workload first: this scenario tells us the API has spare capacity. More API replicas would not remove the database reads.';}if(b.dataset.action){const a=b.dataset.action;let msg='';if(a==='request'){setRoute('direct');msg='Another request, another database lookup.'}if(a==='miss'){setRoute('miss');$('cache-caption').textContent='Empty, then populated';msg='Follow the miss: check, read, store, respond.'}if(a==='hit'){setRoute('hit');$('cache-caption').textContent='Cached destination';msg='The database is skipped on this cache hit.'}if(a==='stale'){setRoute('stale');$('cache-caption').textContent='/show-v1 · old copy';msg='The old destination is returned. Speed does not guarantee freshness.'}if(a==='expire'){setRoute('miss');$('cache-caption').textContent='Expired → refresh to v2';msg='Expiry removes the old copy. This request reads /show-v2 from the database and stores a fresh copy.'}if($('feedback'))$('feedback').textContent=msg;paused=false;syncPause();}});
document.addEventListener('input',e=>{if(e.target.id==='traffic'){trafficLevel=Number(e.target.value)-1;renderAudience();setRoute(lessons[step].route);$('feedback').textContent=`${trafficProfiles[trafficLevel].label}: more arriving users produce more request markers. ${step===2?'Red × markers show database reads that time out.':'Every request still needs a database lookup.'}`;}});
window.addEventListener('hashchange',fromHash);reduced.addEventListener('change',e=>{paused=e.matches;syncPause()});

function svgElement(tag,attrs){const el=document.createElementNS('http://www.w3.org/2000/svg',tag);Object.entries(attrs).forEach(([key,value])=>el.setAttribute(key,value));return el;}
function profile(){return trafficProfiles[step===0?0:trafficLevel];}
function renderAudience(){const p=profile(),colors=['#aed39d','#efb583','#b9a5d7','#a2c5e6','#eacc83'];$('visitor-count').textContent=p.label;if($('traffic-label'))$('traffic-label').textContent=p.label;const people=$('people');people.replaceChildren();const columns=p.figures===1?1:p.figures<=3?3:5;for(let i=0;i<p.figures;i++){const row=Math.floor(i/columns),col=i%columns,x=115+(col-(Math.min(columns,p.figures)-1)/2)*22+(row-1)*6,y=204+row*16-Math.abs(col-(Math.min(columns,p.figures)-1)/2)*3;const person=svgElement('g',{transform:`translate(${x} ${y})`});person.append(svgElement('ellipse',{cx:2,cy:28,rx:10,ry:4,fill:'var(--person-shadow)'}),svgElement('rect',{x:-7,y:9,width:14,height:17,rx:5,fill:`var(--person-${i%colors.length}, ${colors[i%colors.length]})`,stroke:'var(--person-outline)','stroke-width':1.5}),svgElement('circle',{cx:0,cy:5,r:5.5,fill:'var(--person-head)',stroke:'var(--person-outline)','stroke-width':1.5}));person.append(svgElement('path',{d:'M3 12Q6 12 6 17V22Q6 25 3 25',fill:'none',stroke:'var(--person-shadow)','stroke-width':2}));people.append(person);}}
function updateTotals(){$('cache-hits').textContent=`${cacheHits} cache hits`;}
function resetTraffic(){flows=[];flowTime=0;nextArrival=0;flowSerial=0;sent=0;completed=0;failed=0;databaseReads=0;cacheHits=0;updateTotals();}
function spawnFlow(){const id=flowSerial++,willFail=step===2 && id%3===1;const legs=willFail?[routes.slow[0],routes.slow[1]]:segments;const el=svgElement('g',{'aria-hidden':'true'}),circle=svgElement('circle',{r:6,'stroke-width':2.5}),cross=svgElement('path',{d:'M-3 -3L3 3M3 -3L-3 3',fill:'none',stroke:'#fff','stroke-width':2,'stroke-linecap':'round',display:'none'});el.append(circle,cross);$('packets').append(el);let duration=0,dbAt=null,hitAt=null;for(const leg of legs){duration+=(leg[2]||1)*850;if(leg[0]==='api-db')dbAt=duration;if((route==='hit'||route==='stale')&&leg[0]==='cache-api')hitAt=duration;}flows.push({id,legs,willFail,dbAt,hitAt,dbRecorded:false,hitRecorded:false,born:flowTime,el,circle,cross,counted:false});sent++;updateTotals();}
function tick(time){const dt=previous?Math.min(time-previous,80):0;previous=time;if(!paused){elapsed+=dt;flowTime+=dt;if(flowTime>=nextArrival){spawnFlow();nextArrival=flowTime+profile().interval;}const unit=850;flows=flows.filter(flow=>{let age=flowTime-flow.born,index=0;if(flow.dbAt!==null&&!flow.dbRecorded&&age>=flow.dbAt){flow.dbRecorded=true;databaseReads++;updateTotals();}if(flow.hitAt!==null&&!flow.hitRecorded&&age>=flow.hitAt){flow.hitRecorded=true;cacheHits++;updateTotals();}for(;index<flow.legs.length;index++){const duration=(flow.legs[index][2]||1)*unit;if(age<duration)break;age-=duration;}if(index===flow.legs.length){if(!flow.counted){flow.counted=true;if(flow.willFail)failed++;else completed++;updateTotals();}if(!flow.willFail || age>400){flow.el.remove();return false;}const path=$('api-db'),point=path.getPointAtLength(path.getTotalLength());flow.el.setAttribute('transform',`translate(${point.x} ${point.y})`);flow.circle.setAttribute('fill','var(--failure)');flow.circle.setAttribute('stroke','#fff');flow.circle.setAttribute('r',10);flow.cross.setAttribute('display','');flow.el.setAttribute('opacity',Math.min(1,(400-age)/280));return true;}const seg=flow.legs[index],path=$(seg[0]),point=path.getPointAtLength(path.getTotalLength()*age/((seg[2]||1)*unit)),response=seg[0]==='api-client'||seg[0]==='db-api'||seg[0]==='cache-api';flow.el.setAttribute('transform',`translate(${point.x} ${point.y})`);flow.circle.setAttribute('fill',response?'var(--response-fill)':'var(--request)');flow.circle.setAttribute('stroke',response?'var(--response)':'var(--request)');return true;});const total=segments.reduce((n,leg)=>n+(leg[2]||1)*unit,0)+650;let position=elapsed%total,index=0;for(;index<segments.length;index++){const duration=(segments[index][2]||1)*unit;if(position<duration)break;position-=duration;}if(index<segments.length)showTrace(index);}requestAnimationFrame(tick);}
const colorScheme=matchMedia('(prefers-color-scheme: dark)');
let savedTheme=null;try{savedTheme=localStorage.getItem('system-stories-theme')}catch{}
function applyTheme(theme){document.documentElement.dataset.theme=theme;const dark=theme==='dark';$('theme-toggle').setAttribute('title',dark?'Switch to light mode':'Switch to dark mode');$('theme-toggle').setAttribute('aria-label',dark?'Switch to light mode':'Switch to dark mode');$('theme-toggle').setAttribute('aria-pressed',String(dark));}
applyTheme(savedTheme==='light'||savedTheme==='dark'?savedTheme:colorScheme.matches?'dark':'light');
$('theme-toggle').onclick=()=>{savedTheme=document.documentElement.dataset.theme==='dark'?'light':'dark';applyTheme(savedTheme);try{localStorage.setItem('system-stories-theme',savedTheme)}catch{}};
colorScheme.addEventListener('change',e=>{if(savedTheme!=='light'&&savedTheme!=='dark')applyTheme(e.matches?'dark':'light')});
document.addEventListener('keydown',e=>{if(e.defaultPrevented||e.repeat||e.altKey||e.ctrlKey||e.metaKey||e.shiftKey||e.isComposing)return;const target=e.target;if(target?.isContentEditable||target?.closest('input,textarea,select,[contenteditable]:not([contenteditable="false"]),[role="slider"],[role="textbox"],[role="combobox"]'))return;if(e.key==='ArrowRight'){e.preventDefault();$('next').onclick()}else if(e.key==='ArrowLeft'&&step>0){e.preventDefault();$('back').onclick()}});
fromHash();requestAnimationFrame(tick);
